REAL = ("REALISM: it must look like a real photograph taken on a recent flagship phone by a person, not a render: natural depth of field, very light sensor grain, "
 "slightly imperfect framing, true-to-life colour, believable soft shadows. Leather shows real grain, pores, micro-creases and painted edges, never airbrushed or plastic; "
 "stitching is individual and slightly uneven like handwork. No HDR glow, no oversaturation, no catalogue perfection, no lens flare, no AI sheen.")
DONT = ("DO NOT: no coins anywhere, no city names, no word \"workshop\", no \"Black Friday\", no \"sale\" wording, no \"only X left\", no countdown, no stars or review quotes, "
 "no faces or heads (hands cropped at the wrist are fine), no visible third-party brand logos, no extra products beyond those described, no redesign or recolour of the uploaded "
 "product, no added embossing or patterns on the leather, no misspelled or extra text beyond the exact lines given, no watermark, no borders, no frames.")
SIZE = "SIZE: exactly 1080 x 1350 pixels, vertical 4:5, sRGB, sharp, high-resolution JPG, no borders. SAFE AREA: keep every text line and the logo at least 90 px away from all four edges (Reels and Feed crop the edges)."
LOGO = "LOGO: the uploaded Kordovan horse-head logo PNG exactly as supplied (do not redraw it), recoloured {c}, 110 px wide, {pos}."


